{"content":"'use strict';

const http = require('node:http');
const path = require('node:path');
const fs = require('node:fs/promises');

const DEFAULT_DATA_PATH = 'data/levels.json';
const DEFAULT_STATIC_ROOT = 'web/';
const API_LEVELS_PATH = '/api/levels';
const LEVEL_COUNT = 5;

const ERROR_CODES = {
  LEVEL_DATA_UNAVAILABLE: 'LEVEL_DATA_UNAVAILABLE',
  NOT_FOUND: 'NOT_FOUND',
  METHOD_NOT_ALLOWED: 'METHOD_NOT_ALLOWED',
  INTERNAL_ERROR: 'INTERNAL_ERROR',
};

const JSON_UTF8 = 'application/json; charset=utf-8';
const TEXT_UTF8 = 'text/plain; charset=utf-8';

const CONTENT_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': JSON_UTF8,
  '.txt': TEXT_UTF8,
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.webp': 'image/webp',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
};
const DEFAULT_CONTENT_TYPE = 'application/octet-stream';

function createDataError(message) {
  const error = new Error(message);
  error.code = ERROR_CODES.LEVEL_DATA_UNAVAILABLE;
  return error;
}

function validateLevels(value) {
  if (!Array.isArray(value)) {
    throw createDataError('关卡数据顶层必须是数组');
  }
  if (value.length !== LEVEL_COUNT) {
    throw createDataError(`关卡数据必须恰为 ${LEVEL_COUNT} 项，实际 ${value.length} 项`);
  }
  value.forEach((level, index) => {
    const where = `关卡数据第 ${index + 1} 项`;
    if (level === null || typeof level !== 'object' || Array.isArray(level)) {
      throw createDataError(`${where}必须是对象`);
    }
    if (!Number.isInteger(level.id) || level.id < 1) {
      throw createDataError(`${where}的 id 必须是正整数`);
    }
    if (typeof level.name !== 'string' || level.name.trim() === '') {
      throw createDataError(`${where}的 name 必须是非空字符串`);
    }
  });
  return value;
}

async function readLevels(dataPath) {
  let raw;
  try {
    raw = await fs.readFile(dataPath, 'utf8');
  } catch (cause) {
    throw createDataError(`关卡数据文件不可读：${cause.code ?? cause.message}`);
  }
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw createDataError('关卡数据不是合法 JSON');
  }
  return validateLevels(parsed);
}

function sendJson(response, statusCode, payload) {
  const body = JSON.stringify(payload);
  response.writeHead(statusCode, {
    'Content-Type': JSON_UTF8,
    'Content-Length': Buffer.byteLength(body),
  });
  response.end(body);
}

function sendError(response, statusCode, code, message) {
  sendJson(response, statusCode, { error: { code, message } });
}

function sendText(response, statusCode, message) {
  response.writeHead(statusCode, {
    'Content-Type': TEXT_UTF8,
    'Content-Length': Buffer.byteLength(message),
  });
  response.end(message);
}

async function handleApiLevels(request, response, dataPath) {
  if (request.method !== 'GET') {
    sendError(response, 405, ERROR_CODES.METHOD_NOT_ALLOWED, '该资源仅支持 GET 方法');
    return;
  }
  let levels;
  try {
    levels = await readLevels(dataPath);
  } catch (error) {
    if (error.code !== ERROR_CODES.LEVEL_DATA_UNAVAILABLE) {
      throw error;
    }
    sendError(response, 500, error.code, error.message);
    return;
  }
  sendJson(response, 200, levels);
}

async function sendStaticFile(response, filePath) {
  let body;
  try {
    body = await fs.readFile(filePath);
  } catch {
    sendText(response, 404, 'Not Found');
    return;
  }
  const contentType = CONTENT_TYPES[path.extname(filePath).toLowerCase()] ?? DEFAULT_CONTENT_TYPE;
  response.writeHead(200, {
    'Content-Type': contentType,
    'Content-Length': body.length,
  });
  response.end(body);
}

async function handleStatic(request, response, pathname, staticRoot) {
  if (request.method !== 'GET') {
    sendError(response, 405, ERROR_CODES.METHOD_NOT_ALLOWED, '静态资源仅支持 GET 方法');
    return;
  }
  let decodedPathname;
  try {
    decodedPathname = decodeURIComponent(pathname);
  } catch {
    sendText(response, 404, 'Not Found');
    return;
  }
  const root = path.resolve(staticRoot);
  const filePath = path.resolve(root, `.${decodedPathname}`);
  if (filePath !== root && !filePath.startsWith(root + path.sep)) {
    sendText(response, 404, 'Not Found');
    return;
  }
  let stat;
  try {
    stat = await fs.stat(filePath);
  } catch {
    sendText(response, 404, 'Not Found');
    return;
  }
  if (stat.isDirectory()) {
    await sendDirectoryIndex(response, filePath);
    return;
  }
  if (!stat.isFile()) {
    sendText(response, 404, 'Not Found');
    return;
  }
  await sendStaticFile(response, filePath);
}

async function sendDirectoryIndex(response, directoryPath) {
  const indexPath = path.join(directoryPath, 'index.html');
  let indexStat;
  try {
    indexStat = await fs.stat(indexPath);
  } catch {
    sendText(response, 404, 'Not Found');
    return;
  }
  if (!indexStat.isFile()) {
    sendText(response, 404, 'Not Found');
    return;
  }
  await sendStaticFile(response, indexPath);
}

async function handleRequest(request, response, options) {
  let pathname;
  try {
    pathname = new URL(request.url, 'http://localhost').pathname;
  } catch {
    sendText(response, 404, 'Not Found');
    return;
  }
  if (pathname === API_LEVELS_PATH) {
    await handleApiLevels(request, response, options.dataPath);
    return;
  }
  if (pathname === '/api' || pathname.startsWith('/api/')) {
    sendError(response, 404, ERROR_CODES.NOT_FOUND, '未知 API 路径');
    return;
  }
  await handleStatic(request, response, pathname, options.staticRoot);
}

function createServer(options = {}) {
  const resolvedOptions = {
    dataPath: options.dataPath ?? DEFAULT_DATA_PATH,
    staticRoot: options.staticRoot ?? DEFAULT_STATIC_ROOT,
  };
  return http.createServer(async (request, response) => {
    try {
      await handleRequest(request, response, resolvedOptions);
    } catch (error) {
      if (!response.headersSent) {
        sendError(response, 500, ERROR_CODES.INTERNAL_ERROR, '服务器内部错误');
      } else {
        response.end();
      }
    }
  });
}

async function start({ port = 0, dataPath, staticRoot } = {}) {
  const server = createServer({ dataPath, staticRoot });
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, '127.0.0.1', () => {
      server.removeListener('error', reject);
      resolve();
    });
  });
  const { port: boundPort } = server.address();
  async function stop() {
    if (!server.listening) {
      return;
    }
    await new Promise((resolve, reject) => {
      server.close((error) => (error ? reject(error) : resolve()));
    });
    server.closeAllConnections();
  }
  return {
    origin: `http://127.0.0.1:${boundPort}`,
    port: boundPort,
    stop,
  };
}

module.exports = { createServer, start };
