162	  } catch {
163	    sendText(response, 404, 'Not Found');
164	    return;
165	  }
166	  if (stat.isDirectory()) {
167	    await sendDirectoryIndex(response, filePath);
168	    return;
169	  }
170	  if (!stat.isFile()) {
171	    sendText(response, 404, 'Not Found');
