const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const WEB_ROOT = path.join(__dirname, '..', '..', 'web');
const INDEX_HTML_PATH = path.join(WEB_ROOT, 'index.html');
const LEVEL_SELECT_PATH = path.join(WEB_ROOT, 'level-select.js');

function readWebFile(filePath) {
  return fs.readFileSync(filePath, 'utf8');
}

test('web/index.html 含 loading、level-list、error-message 三个容器', () => {
  const html = readWebFile(INDEX_HTML_PATH);
  assert.match(html, /id="loading"/);
  assert.match(html, /id="level-list"/);
  assert.match(html, /id="error-message"/);
});

test('web/index.html 以 script 引用 level-select.js', () => {
  const html = readWebFile(INDEX_HTML_PATH);
  assert.match(html, /<script[^>]*src="level-select\.js"/);
});

test('web/index.html 与 web/level-select.js 未引用外部网络资源（CHECK-004）', () => {
  const html = readWebFile(INDEX_HTML_PATH);
  const js = readWebFile(LEVEL_SELECT_PATH);
  assert.doesNotMatch(html, /https?:\/\//);
  assert.doesNotMatch(js, /https?:\/\//);
});

test('web/level-select.js 未引用任何 npm 包（CHECK-004）', () => {
  const js = readWebFile(LEVEL_SELECT_PATH);
  assert.doesNotMatch(js, /\brequire\s*\(/);
  assert.doesNotMatch(js, /^\s*import\s/m);
  assert.doesNotMatch(js, /\bimport\s*\(/);
  assert.doesNotMatch(js, /\bnode:/);
});
