const test = require('node:test');
const assert = require('node:assert/strict');
const { createFakeDocument } = require('./helpers/fake-dom.js');

const { initLevelSelect } = require('../../web/level-select.js');

const CONTAINER_IDS = ['loading', 'level-list', 'error-message'];

const SAMPLE_LEVELS = [
  { id: 1, name: '木叶村入口', difficulty: 1, unlocked: true },
  { id: 2, name: '死亡森林', difficulty: 2, unlocked: true },
  { id: 3, name: '中忍考试会场', difficulty: 3, unlocked: true },
  { id: 4, name: '终结之谷', difficulty: 4, unlocked: false },
  { id: 5, name: '晓之巢穴', difficulty: 5, unlocked: false },
];

function okResponse(payload) {
  return { ok: true, status: 200, json: async () => payload };
}

function statusResponse(status) {
  return { ok: false, status, json: async () => ({}) };
}

function recordingFetchImpl(payload) {
  const requests = [];
  const fetchImpl = async (url) => {
    requests.push(url);
    return okResponse(payload);
  };
  fetchImpl.requests = requests;
  return fetchImpl;
}

async function runLevelSelect(fetchImpl) {
  const document = createFakeDocument(CONTAINER_IDS);
  await initLevelSelect({ document, fetchImpl });
  return document;
}

test('initLevelSelect 以相对路径 /api/levels 发起请求', async () => {
  const fetchImpl = recordingFetchImpl(SAMPLE_LEVELS);
