});

test('initLevelSelect 收到满足字段约束的五项数组时结束加载态并以文本节点渲染名称与难度', async () => {
  const fetchImpl = recordingFetchImpl(SAMPLE_LEVELS);
  const document = await runLevelSelect(fetchImpl);

  const loading = document.getElementById('loading');
  assert.equal(loading.hidden, true);

  const levelList = document.getElementById('level-list');
  assert.equal(levelList.children.length, 5);
  levelList.children.forEach((item, index) => {
    const level = SAMPLE_LEVELS[index];
    const textNodes = item.children.filter((child) => child.nodeType === 3);
    const texts = textNodes.map((node) => node.textContent);
    assert.ok(
      texts.includes(level.name),
      `第 ${index + 1} 项应以文本节点渲染关卡名称 ${level.name}`
    );
    assert.ok(
      texts.some((text) => text.includes(String(level.difficulty))),
      `第 ${index + 1} 项应以文本节点渲染难度 ${level.difficulty}`
    );
  });
});

test('initLevelSelect 成功时清空并隐藏错误容器', async () => {
