  assert.equal(errorMessage.hidden, true);
  assert.equal(errorMessage.textContent, '');
});

test('initLevelSelect 令 unlocked=false 的项呈锁定态且不可选择，其余项不锁定', async () => {
  const fetchImpl = recordingFetchImpl(SAMPLE_LEVELS);
  const document = await runLevelSelect(fetchImpl);

  const levelList = document.getElementById('level-list');
  SAMPLE_LEVELS.forEach((level, index) => {
    const item = levelList.children[index];
    assert.equal(
      item.classList.contains('locked'),
      level.unlocked === false,
      `第 ${index + 1} 项锁定态应为 ${level.unlocked === false}`
    );
    assert.equal(
      item.getAttribute('aria-disabled'),
      level.unlocked === false ? 'true' : null
    );
  });
});

async function assertErrorBranch(fetchImpl, extraAssert) {
  const document = await runLevelSelect(fetchImpl);

  const loading = document.getElementById('loading');
  assert.equal(loading.hidden, true, '错误分支必须结束加载态');

  const errorMessage = document.getElementById('error-message');
  assert.equal(errorMessage.hidden, false, '错误分支必须展示错误容器');
  assert.equal(typeof errorMessage.textContent, 'string');
  assert.ok(errorMessage.textContent.trim().length > 0, '错误信息必须可读非空');

  const levelList = document.getElementById('level-list');
  assert.equal(levelList.children.length, 0, '错误分支不应渲染关卡列表');

  for (const id of CONTAINER_IDS) {
    assert.notEqual(document.getElementById(id), null, `页面框架容器 ${id} 必须保留`);
  }

  if (extraAssert) {
    extraAssert(errorMessage);
  }
}

