(function (root) {
  const REQUIRED_LEVEL_COUNT = 5;
  const API_LEVELS_PATH = '/api/levels';

  function validateLevelsPayload(payload) {
    if (!Array.isArray(payload)) {
      throw new Error('关卡数据格式不正确：顶层必须是数组');
    }
    if (payload.length !== REQUIRED_LEVEL_COUNT) {
      throw new Error(
        `关卡数据格式不正确：必须恰为 ${REQUIRED_LEVEL_COUNT} 项，实际 ${payload.length} 项`
      );
    }
    for (let index = 0; index < payload.length; index += 1) {
      const level = payload[index];
      if (
        level === null ||
        typeof level !== 'object' ||
        Array.isArray(level) ||
        typeof level.name !== 'string' ||
        level.name.trim() === ''
      ) {
        throw new Error(`关卡数据格式不正确：第 ${index + 1} 项缺少有效的关卡名称`);
      }
    }
    return payload;
  }

  function renderLevelItem(document, level) {
    const item = document.createElement('li');
    item.className = 'level-item';
    item.appendChild(document.createTextNode(level.name));
    item.appendChild(
      document.createTextNode(`难度：${level.difficulty ?? '未知'}`)
    );
    if (level.unlocked === false) {
      item.classList.add('locked');
      item.setAttribute('aria-disabled', 'true');
    }
    return item;
  }

  async function initLevelSelect({ document, fetchImpl } = {}) {
    if (!document) {
      throw new Error('initLevelSelect 需要注入 document');
    }
    if (typeof fetchImpl !== 'function') {
      throw new Error('initLevelSelect 需要注入 fetchImpl');
    }

    const loading = document.getElementById('loading');
    const levelList = document.getElementById('level-list');
    const errorMessage = document.getElementById('error-message');

    const finishLoading = () => {
      if (loading) {
        loading.hidden = true;
      }
    };

    const showError = (message) => {
      finishLoading();
      if (errorMessage) {
        errorMessage.textContent = message;
        errorMessage.hidden = false;
      }
    };

    const showClearLevels = () => {
      finishLoading();
      if (errorMessage) {
        errorMessage.textContent = '';
        errorMessage.hidden = true;
      }
      if (levelList) {
        levelList.children.length = 0;
        for (const level of arguments[1]) {
          levelList.appendChild(renderLevelItem(document, level));
        }
      }
    };

    try {
      const response = await fetchImpl(API_LEVELS_PATH);
      if (!response || response.ok !== true) {
        const status = response && response.status ? response.status : '未知';
        throw new Error(`关卡数据请求失败（状态码 ${status}），请稍后重试`);
      }
      let payload;
      try {
        payload = await response.json();
      } catch {
        throw new Error('关卡数据不是合法 JSON，请稍后重试');
      }
      validateLevelsPayload(payload);
      finishLoading();
      if (errorMessage) {
        errorMessage.textContent = '';
        errorMessage.hidden = true;
      }
      if (levelList) {
        for (const level of payload) {
          levelList.appendChild(renderLevelItem(document, level));
        }
      }
    } catch (error) {
      showError(
        `关卡数据加载失败：${error && error.message ? error.message : '未知错误'}`
      );
    }
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { initLevelSelect };
  } else if (root && typeof document !== 'undefined') {
    const boot = () => {
      initLevelSelect({ document, fetchImpl: (...args) => fetch(...args) });
    };
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', boot);
    } else {
      boot();
    }
  }
})(typeof globalThis !== 'undefined' ? globalThis : this);
